int online_pages_range(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct online_pg_range range;
    int nid = pfn_to_nid(pfn);

    lock_memory_hotplug();

    /* Initialize the online notification structure */
    memset(&range, 0, sizeof(range));
    range.start_pfn = pfn;
    range.nr_pages = nr_pages;
    range.nid = nid;

    /* Check if the node is present */
    if (!node_online(nid)) {
        range.nid = NUMA_NO_NODE;
    }

    /* Notify that memory is going online */
    ret = send_online_notification(&range);
    if (ret < 0) {
        unlock_memory_hotplug();
        return ret;
    }

    /* Check if zone is populated and possibly rebuild zonelists */
    if (is_zone_populated(range.nid, range.start_pfn)) {
        rebuild_zonelists();
    }

    /* Attempt to online the specified range of pages */
    ret = online_pages(range.start_pfn, range.nr_pages);
    if (ret < 0) {
        unlock_memory_hotplug();
        return ret;
    }

    update_zone_statistics(range.start_pfn, range.nr_pages);

    /* Notify that memory is online */
    send_online_complete_notification(&range);

    unlock_memory_hotplug();
    return ret;
}

int online_pages(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct online_region region = {0};
    int nid = page_to_nid(pfn_to_page(pfn));
    int present = node_online(nid);

    lock_memory_hotplug();

    if (!present) {
        region.nid = nid;
        send_online_notification(&region);
        if (ret < 0) {
            unlock_memory_hotplug();
            return ret;
        }
    }

    if (!zone_populated(&zone)) {
        rebuild_zonelists();
    }

    ret = online_page_range(pfn, nr_pages);
    if (ret < 0) {
        unlock_memory_hotplug();
        return ret;
    }

    update_zone_stat(&zone, nr_pages);
    if (should_rebuild_zonelist()) {
        rebuild_zonelists();
    }

    send_online_complete_notification(&region);
    unlock_memory_hotplug();

    return ret;
}

#include <linux/memblock.h>
#include <linux/memory.h>
#include <linux/mmzone.h>

int online_memory_pages(unsigned long pfn, unsigned long nr_pages) {
    int result = 0;
    struct memory_notify mem_event = {0};

    lock_memory_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        mem_event.status_change_nid = pfn_to_nid(pfn);
    }

    mem_event.start_pfn = pfn;
    mem_event.nr_pages = nr_pages;

    result = online_pages(pfn, nr_pages);
    if (result < 0) {
        goto unlock_exit;
    }

    if (result == 0 && need_zonelist_rebuild()) {
        rebuild_zonelist();
    }

    mem_event.status = MEM_ONLINE;
    notify_memory_event(&mem_event);

unlock_exit:
    unlock_memory_hotplug();
    return result;
}

int online_memory_pages(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct memory_notify arg = {0};

    lock_memory_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        arg.status_change_nid = pfn_to_nid(pfn);
    }

    arg.start_pfn = pfn;
    arg.end_pfn = pfn + nr_pages;

    ret = send_memory_notify(MEM_GOING_ONLINE, &arg);
    if (ret) {
        unlock_memory_hotplug();
        return ret;
    }

    if (zone_spanned_pages(zone) > zone->present_pages) {
        rebuild_zonelist();
    }

    ret = online_page_range(pfn, nr_pages);
    if (!ret) {
        update_zone_statistics(zone);
        if (need_zonelist_rebuild())
            rebuild_zonelist();
        send_memory_notify(MEM_ONLINE, &arg);
    }

    unlock_memory_hotplug();
    return ret;
}

int online_memory_range(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    int nid = pgdat_to_nid(pfn_to_page(pfn));
    struct online_memory_notification notification;

    mutex_lock(&memory_hotplug_mutex);

    if (!node_online(nid))
        notification.nid = nid;

    notification.type = MEM_GOING_ONLINE;
    ret = send_memory_notification(&notification);
    if (ret) {
        mutex_unlock(&memory_hotplug_mutex);
        return ret;
    }

    if (!zonelist_populated())
        rebuild_zonelist();

    ret = online_pages(pfn, nr_pages);
    if (ret)
        goto unlock_and_exit;

    update_zone_statistics(pfn, nr_pages);
    if (should_rebuild_zonelist())
        rebuild_zonelist();

    notification.type = MEM_ONLINE;
    send_memory_notification(&notification);

unlock_and_exit:
    mutex_unlock(&memory_hotplug_mutex);
    return ret;
}
